// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    Attacker attacker;

    function setUp() public {
        c = new ReentrancyDAO();
        attacker = new Attacker(c);
    }

    function testFuzz_property(uint256 amount, uint256 seed) public {
        amount = bound(amount, 1, 1e30);
        seed; // keep wide fuzz domain

        // adversarial re-entrant counterparty is the actor
        vm.deal(address(attacker), amount);
        vm.prank(address(attacker));
        c.deposit{value: amount}();

        bool ok;
        try attacker.pwn() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a re-entrant withdrawal during the payout must be inert
        // (credit already zeroed), so the full flow succeeds and drains c exactly once.
        assertTrue(ok && address(c).balance == 0);
    }
}

contract Attacker {
    ReentrancyDAO c;
    constructor(ReentrancyDAO _c) { c = _c; }

    function pwn() external {
        c.withdrawAll();
    }

    fallback() external payable {
        c.withdrawAll();
    }
}
